"use strict";const STORAGE_KEY = "qc_profile_v1";const MAX_HISTORY_ENTRIES = 50;export const PROFILE_UPDATED_EVENT = "qc:profile:updated";const DEFAULT_PROFILE = Object.freeze({theme:"system",sidebarCollapsed:false,shortcutsEnabled:true,searchHistory:[],favourites:[],lastVisitedNodeId:null,toastDuration:2500,experimentalFeatures:false,created:new Date().toISOString(),updated:new Date().toISOString(),});const getCurrentTimestamp = () => new Date().toISOString();const safelyParseJSON = (json) =>{try{return JSON.parse(json);}catch (error){console.warn("[Profile] Corrupt JSON data - resetting to defaults.",error);return null;}};const dispatchProfileUpdate = (profile) =>{window.dispatchEvent( new CustomEvent(PROFILE_UPDATED_EVENT,{detail:profile}),);};const writeToStorage = (data) =>{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));};export function loadProfile(){const storedData = safelyParseJSON(localStorage.getItem(STORAGE_KEY));if (!storedData){writeToStorage(DEFAULT_PROFILE);return{...DEFAULT_PROFILE};}return{...DEFAULT_PROFILE,...storedData};}export function saveProfile(profileData){const completeProfile ={...DEFAULT_PROFILE,...profileData,updated:getCurrentTimestamp(),};try{writeToStorage(completeProfile);dispatchProfileUpdate(completeProfile);return completeProfile;}catch (error){console.error("[Profile] Failed to save profile",error);return null;}}export function updateProfile(partialUpdate){return saveProfile({...loadProfile(),...partialUpdate});}export function resetProfile(){const currentProfile = loadProfile();const resetProfile ={...DEFAULT_PROFILE,created:currentProfile.created,updated:getCurrentTimestamp(),};writeToStorage(resetProfile);dispatchProfileUpdate(resetProfile);return resetProfile;}export function getEffectiveTheme(){const{theme}= loadProfile();if (theme === "system"){return window.matchMedia("(prefers-color-scheme:light)").matches ? "light":"dark";}return theme;}export function toggleTheme(){const currentTheme = loadProfile().theme;let nextTheme;switch (currentTheme){case "light":nextTheme = "dark";break;case "dark":nextTheme = "system";break;default:nextTheme = "light";}return updateProfile({theme:nextTheme});}export function addSearchQuery(query){const{searchHistory}= loadProfile();const updatedHistory = [ query,...searchHistory.filter((existingQuery) => existingQuery !== query),].slice(0,MAX_HISTORY_ENTRIES);return updateProfile({searchHistory:updatedHistory});}export function addFavourite(nodeId){const{favourites}= loadProfile();if (favourites.includes(nodeId)){return loadProfile();}return updateProfile({favourites:[...favourites,nodeId],});}export function removeFavourite(nodeId){const{favourites}= loadProfile();return updateProfile({favourites:favourites.filter((id) => id !== nodeId),});}window.addEventListener("storage",(event) =>{if (event.key === STORAGE_KEY){const updatedProfile = safelyParseJSON(event.newValue) ||{...DEFAULT_PROFILE,};dispatchProfileUpdate(updatedProfile);}});const systemThemeMediaQuery = window.matchMedia("(prefers-color-scheme:dark)");systemThemeMediaQuery.addEventListener("change",() =>{if (loadProfile().theme === "system"){dispatchProfileUpdate(loadProfile());}});dispatchProfileUpdate(loadProfile());export const ProfileAPI ={loadProfile,saveProfile,updateProfile,resetProfile,getEffectiveTheme,toggleTheme,addSearchQuery,addFavourite,removeFavourite,};window.Profile = ProfileAPI;